import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.ApplicationContext; import org.springframework.data.mongodb.core.MongoTemplate; import org.springframework.data.mongodb.core.aggregation.*; import org.springframework.data.domain.Sort; import java.util.List; @SpringBootApplication public class AggTest { public static void main(String[] args) { ApplicationContext ctx = SpringApplication.run(AggTest.class, args); MongoTemplate mt = ctx.getBean(MongoTemplate.class); Aggregation agg = Aggregation.newAggregation(Aggregation.group("responsavel.matricula", "responsavel.nome").count().as("qtdDemanda"), Aggregation.project("qtdDemanda").and("_id.matricula").as("matricula").and("_id.nome").as("nome")); System.out.println("--- RESULT ---"); System.out.println(mt.aggregate(agg, "demandas", org.bson.Document.class).getRawResults().toJson()); System.exit(0); } }
